{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) to counteract overconfidence.",
    "Increase forecast sensitivity to recent price spikes (last 5-7 days) when sentiment is positive (sentiment > 0.00) to avoid lagged reactions.",
    "Apply mean reversion bias: if forecast is consistently above true outcome over 3-5 days, reduce forecast by 5-10% to align with historical mean.",
    "Reduce forecast overshoot after sharp upward spikes (≥ 10% from prior day) by 15-20% to prevent overcorrection.",
    "When sentiment is positive and price is trending upward, slightly increase forecast horizon by 1-2 days to capture momentum.",
    "If true outcome consistently exceeds forecast by > 5% over 30-day window, shift model toward higher volatility weighting for next period."
  ]
}
